export const text=v=>typeof v==='string'?v:'';
export function contactData(value={}){const v=value&&typeof value==='object'?value:{};return {recipient:text(v.recipient),phone:text(v.phone),email:text(v.email),phoneVerified:v.phoneVerified===true,emailVerified:v.emailVerified===true,smsConsent:v.smsConsent===true,consentSource:text(v.consentSource),consentDate:text(v.consentDate),suppressed:v.suppressed===true,drafts:Object.fromEntries(['letter','call','sms','email'].map(k=>[k,text(v.drafts?.[k])])),events:Array.isArray(v.events)?v.events.map(e=>({at:text(e.at),channel:text(e.channel),outcome:text(e.outcome),note:text(e.note)})):[]};}
export function phoneURI(s){const p=String(s||'').replace(/[\s().-]/g,'');return /^\+?[0-9]{10,15}$/.test(p)?'tel:'+p:'';}
export function emailURI(email,subject,body){return /^[^\s@?&#]+@[^\s@?&#]+\.[^\s@?&#]+$/.test(email)?'mailto:'+encodeURIComponent(email)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body):'';}
export function blockReason(r,c,channel){if(r.demo)return 'Fictional samples cannot be used for outreach.';if(r.stage==='Do not contact'||c.suppressed)return 'Do not contact is active.';if(r.stage==='Closed')return 'This property is closed.';const age=Date.now()-Date.parse(r.verifiedAt);if(!Object.values(r.checks||{}).every(Boolean)||Object.keys(r.checks||{}).length!==4||!Number.isFinite(age)||age<0||age>=30*86400000)return 'Complete the four property checks with a current verification date first.';if(!c.recipient.trim())return 'Enter a verified recipient.';if(channel==='letter'&&!r.mail?.trim())return 'Enter a verified mailing address.';if(['call','sms'].includes(channel)&&(!c.phoneVerified||!phoneURI(c.phone)))return 'Enter and verify the recipient phone number.';if(channel==='sms'&&(!c.smsConsent||!c.consentSource.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(c.consentDate)||!Number.isFinite(Date.parse(c.consentDate))||Date.parse(c.consentDate)>Date.now()))return 'Record SMS consent, its source, and a valid date first.';if(channel==='email'&&(!c.emailVerified||!emailURI(c.email,'','')))return 'Enter and verify the recipient email address.';return '';}
export function defaultDraft(channel,r,s){const address=r.address||'the property identified as '+r.parcel;const intro=`Hello, my name is ${s.name||'Ermias'} with ${s.business||'Baruch-Ermi LLC'}.`;const ask=`If you are considering selling ${address}, I would be happy to learn about your plans and discuss whether I can help. There is no obligation.`;if(channel==='sms')return `${intro} ${ask} Reply STOP to opt out.`;if(channel==='call')return `${intro} Is this a convenient time to talk?\n\n${ask}\n\nIf interested: ask about condition, desired price, timeline, access, and known title issues. Respect a request for no further contact.`;return `${intro}\n\n${ask}\n\nIf this is not relevant, please disregard this ${channel==='letter'?'letter':'email'}.\n\n${s.name||'Ermias Seyoum'}\n${s.business||'Baruch-Ermi LLC'}\n${s.reply||'[Add your reply phone or email]'}${channel==='letter'?'\n'+(s.returnAddress||'[Add your return mailing address]'):''}`;}
